package local.tvmorph.tv;
import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Provider requests stay native. Credentials/stream URLs never enter the web UI. */
final class Xtream{
 final String server,user,password,format;final JSONObject config;private M3uPlaylist m3u;
 Xtream(JSONObject value)throws Exception{if(value.optString("type").equals("m3u")){m3u=new M3uPlaylist(value);config=m3u.config;server=config.getString("server");user="";password="";format="m3u8";return;}value=XtreamCredentials.normalize(value);config=value;URI uri=new URI(value.getString("server").trim());if(!Arrays.asList("http","https").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null)throw new IOException("اكتب رابط المزوّد كاملًا مع http أو https والمنفذ.");server=uri.toString().replaceAll("/+$","");user=value.optString("username");password=value.optString("password");format=value.optString("format","m3u8").equals("ts")?"ts":"m3u8";if(user.isEmpty()||password.isEmpty()||user.length()>256||password.length()>512)throw new IOException("أدخل اسم المستخدم وكلمة السر داخل التطبيق.");}
 static String enc(String value)throws Exception{return URLEncoder.encode(value,"UTF-8").replace("+","%20");}
 private final Map<String,Object> metadata=new LinkedHashMap<>();private final Map<String,Long> metadataTimes=new HashMap<>();private final Map<String,FutureTask<Object>> metadataRequests=new HashMap<>();private int metadataEpoch;
 synchronized void clearMetadata(){if(m3u!=null)m3u.clear();metadataEpoch++;metadata.clear();metadataTimes.clear();metadataRequests.clear();}
 Object request(String action,String key,String id)throws Exception{
  if(!"get_series_info".equals(action)&&!"get_vod_info".equals(action))return networkRequest(action,key,id);
  String cacheKey=action+":"+id;FutureTask<Object> task;int epoch;
  synchronized(this){Long at=metadataTimes.get(cacheKey);if(at!=null&&System.currentTimeMillis()-at<300000)return metadata.get(cacheKey);epoch=metadataEpoch;task=metadataRequests.get(cacheKey);if(task==null){task=new FutureTask<>(()->networkRequest(action,key,id));metadataRequests.put(cacheKey,task);}}
  task.run();try{Object value=task.get();synchronized(this){if(epoch==metadataEpoch&&value.toString().length()<1048576){metadata.put(cacheKey,value);metadataTimes.put(cacheKey,System.currentTimeMillis());while(metadata.size()>4){String oldest=metadata.keySet().iterator().next();metadata.remove(oldest);metadataTimes.remove(oldest);}}}return value;}catch(ExecutionException e){Throwable cause=e.getCause();if(cause instanceof Exception)throw (Exception)cause;throw new IOException("Provider metadata unavailable");}finally{synchronized(this){if(metadataRequests.get(cacheKey)==task)metadataRequests.remove(cacheKey);}}
 }
 Object networkRequest(String action,String key,String id)throws Exception{
  String url=server+"/player_api.php?username="+enc(user)+"&password="+enc(password)+(action==null?"":"&action="+enc(action))+(key==null?"":"&"+key+"="+enc(id));HttpURLConnection c=null;
  try{c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(18000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Morph TV/0.4");if(c.getResponseCode()!=200)throw new IOException();ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>24*1024*1024)throw new IOException();out.write(b,0,n);}}return new JSONTokener(out.toString("UTF-8")).nextValue();}catch(Exception e){throw new IOException("تعذّر الاتصال بمزوّد IPTV. راجع الرابط والمنفذ والاشتراك واتصال التلفزيون بالإنترنت.");}finally{if(c!=null)c.disconnect();}
 }
 JSONObject auth()throws Exception{if(m3u!=null)return m3u.auth();Object response=request(null,null,null);JSONObject info=response instanceof JSONObject?((JSONObject)response).optJSONObject("user_info"):null;if(info==null||info.optInt("auth")!=1||!info.optString("status","Active").equalsIgnoreCase("Active"))throw new IOException("بيانات الاشتراك غير صحيحة أو الاشتراك غير نشط.");return new JSONObject().put("connected",true).put("name",config.optString("name","My TV")).put("expires",info.optString("exp_date","")).put("live",config.optBoolean("live",true)).put("vod",config.optBoolean("vod",true)).put("series",config.optBoolean("series",true));}
 JSONArray categories(String kind)throws Exception{if(m3u!=null)return m3u.categories(kind);String action=kind.equals("live")?"get_live_categories":kind.equals("vod")?"get_vod_categories":"get_series_categories";Object raw=request(action,null,null);if(!(raw instanceof JSONArray))throw new IOException("المزوّد لم يرجع قائمة تصنيفات صالحة.");return (JSONArray)raw;}
 String providerImage(String value){if(value==null||value.trim().isEmpty()||value.equals("null")||value.equals("N/A"))return "";try{URI u=new URI(server+"/").resolve(value.trim().replace(" ","%20"));return Arrays.asList("http","https").contains(u.getScheme())&&u.getHost()!=null?u.toString():"";}catch(Exception e){return "";}}
 String artwork(JSONObject info,String primary){if(info==null)return "";for(String field:new String[]{primary,"cover_big","cover","stream_icon","movie_image"}){String value=providerImage(info.optString(field,""));if(!value.isEmpty())return value;}return "";}
 static String providerRating(JSONObject info,String fallback){if(info==null)return fallback;for(String field:new String[]{"rating","rating_5based"}){String raw=info.optString(field,"").trim().replace(',','.');if(!raw.matches("[0-9]+(?:\\.[0-9]+)?"))continue;try{double n=Double.parseDouble(raw),max=field.equals("rating")?10:5;if(n>0&&n<=max)return String.valueOf(field.equals("rating")?n:n*2);}catch(NumberFormatException ignored){}}return fallback;}
 JSONArray list(String kind,String category)throws Exception{if(m3u!=null)return m3u.list(kind,category);String action=kind.equals("live")?"get_live_streams":kind.equals("vod")?"get_vod_streams":"get_series";Object raw=request(action,category.isEmpty()?null:"category_id",category);if(!(raw instanceof JSONArray))throw new IOException("قائمة المحتوى غير متاحة عند المزوّد.");JSONArray source=(JSONArray)raw,out=new JSONArray();for(int i=0;i<source.length();i++){JSONObject item=source.optJSONObject(i);if(item==null)continue;String id=item.optString(kind.equals("series")?"series_id":"stream_id");if(!id.matches("[0-9]{1,14}"))continue;out.put(new JSONObject().put("id",id).put("name",item.optString("name","Untitled")).put("icon",artwork(item,kind.equals("series")?"cover":"stream_icon")).put("category",item.optString("category_id")).put("added",item.optLong("added",item.optLong("last_modified",0))).put("kind",kind).put("rating",providerRating(item,"")).put("ext",item.optString("container_extension","mp4")));}return out;}
 JSONArray episodes(String id)throws Exception{if(m3u!=null)return new JSONArray();if(!id.matches("[0-9]{1,14}"))throw new IOException("Invalid series");Object raw=request("get_series_info","series_id",id);if(!(raw instanceof JSONObject))throw new IOException("Episodes unavailable");return normalizeEpisodes((JSONObject)raw);}
 JSONArray normalizeEpisodes(JSONObject raw)throws Exception{Object source=raw.opt("episodes");JSONObject groups=source instanceof JSONObject?(JSONObject)source:new JSONObject();if(source instanceof JSONArray){JSONArray flat=(JSONArray)source;for(int i=0;i<flat.length();i++){JSONObject row=flat.optJSONObject(i);if(row==null)continue;String season=row.optString("season","1");JSONArray bucket=groups.optJSONArray(season);if(bucket==null){bucket=new JSONArray();groups.put(season,bucket);}bucket.put(row);}}
 JSONArray out=new JSONArray();List<String> keys=new ArrayList<>();Iterator<String> it=groups.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys,(a,b)->{try{return Integer.compare(Integer.parseInt(a),Integer.parseInt(b));}catch(Exception e){return a.compareTo(b);}});JSONObject series=raw.optJSONObject("info");for(String season:keys){Object value=groups.opt(season);JSONArray episodes=value instanceof JSONArray?(JSONArray)value:new JSONArray();if(value instanceof JSONObject){JSONObject keyed=(JSONObject)value;Iterator<String> ids=keyed.keys();while(ids.hasNext()){JSONObject row=keyed.optJSONObject(ids.next());if(row!=null)episodes.put(row);}}List<JSONObject> sorted=new ArrayList<>();for(int i=0;i<episodes.length();i++){JSONObject e=episodes.optJSONObject(i);if(e!=null&&e.optString("id").matches("[0-9]{1,14}"))sorted.add(e);}Collections.sort(sorted,(a,b)->Integer.compare(a.optInt("episode_num",0),b.optInt("episode_num",0)));for(int i=0;i<sorted.size();i++){JSONObject e=sorted.get(i),info=e.optJSONObject("info");if(info==null)info=new JSONObject();String icon=artwork(info,"movie_image");if(icon.isEmpty()&&series!=null)icon=artwork(series,"cover");out.put(new JSONObject().put("id",e.optString("id")).put("name","S"+season+" · "+e.optString("title","Episode "+(i+1))).put("season",e.optString("season",season)).put("episode",e.optInt("episode_num",i+1)).put("kind","episode").put("ext",e.optString("container_extension","mp4")).put("icon",icon).put("duration",info.optString("duration","")).put("plot",info.optString("plot","")).put("rating",providerRating(info,"")));}}return out;}

 JSONObject details(JSONObject item)throws Exception{if(m3u!=null)return new JSONObject(item.toString());
  String kind=item.optString("kind"),id=item.optString("id");JSONObject result=new JSONObject(item.toString());
  if(!id.matches("[0-9]{1,14}")||!Arrays.asList("vod","series").contains(kind))return result;
  Object raw=request(kind.equals("vod")?"get_vod_info":"get_series_info",kind.equals("vod")?"vod_id":"series_id",id);
  if(item.optString("kind").equals("series")&&raw instanceof JSONObject){JSONObject eps=((JSONObject)raw).optJSONObject("episodes");JSONArray seasons=new JSONArray();if(eps!=null){List<String> seasonKeys=new ArrayList<>();Iterator<String> si=eps.keys();while(si.hasNext())seasonKeys.add(si.next());Collections.sort(seasonKeys,(a,b)->{try{return Integer.compare(Integer.parseInt(a),Integer.parseInt(b));}catch(Exception e){return a.compareTo(b);}});for(String k:seasonKeys)seasons.put(k);}result.put("seasons",seasons);}
  JSONObject info=raw instanceof JSONObject?((JSONObject)raw).optJSONObject("info"):null;
  if(info!=null){result.put("rating",providerRating(info,result.optString("rating","")));String[][] fields={{"plot","plot"},{"description","plot"},{"genre","genre"},{"releaseDate","released"},{"releasedate","released"},{"release_date","released"},{"duration","duration"},{"cast","cast"},{"director","director"}};for(String[] field:fields){String value=info.optString(field[0],"");if(!value.isEmpty()&&!value.equals("null"))result.put(field[1],value.substring(0,Math.min(value.length(),2000)));}String cover=artwork(info,"movie_image");if(!cover.isEmpty())result.put("icon",cover);}
  return result;
 }
 static String epgText(String value){if(value==null)return "";try{byte[] bytes=java.util.Base64.getDecoder().decode(value);String text=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);if(text.indexOf('\uFFFD')<0&&!text.trim().isEmpty())return text;}catch(Exception ignored){}return value;}
 JSONObject epg(String id)throws Exception{if(m3u!=null)return new JSONObject().put("items",new JSONArray());if(!id.matches("[0-9]{1,14}"))throw new IOException("Invalid channel");Object raw=request("get_short_epg","stream_id",id);JSONArray rows=raw instanceof JSONObject?((JSONObject)raw).optJSONArray("epg_listings"):null,out=new JSONArray();if(rows!=null)for(int i=0;i<Math.min(32,rows.length());i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;long start=row.optLong("start_timestamp",0),end=row.optLong("stop_timestamp",row.optLong("end_timestamp",0));if(start>100000000000L)start/=1000;if(end>100000000000L)end/=1000;if(start<=0||end<=start)continue;String title=epgText(row.optString("title","")),description=epgText(row.optString("description",""));out.put(new JSONObject().put("title",title.substring(0,Math.min(title.length(),500))).put("description",description.substring(0,Math.min(description.length(),4000))).put("start",start).put("end",end));}return new JSONObject().put("items",out);}
 String stream(JSONObject item)throws Exception{if(m3u!=null)return m3u.stream(item);String id=item.optString("id"),kind=item.optString("kind"),ext=item.optString("ext","mp4");if(!id.matches("[0-9]{1,14}")||!Arrays.asList("live","vod","episode").contains(kind))throw new IOException("اختر قناة أو فيلمًا أو حلقة.");if(!ext.matches("[A-Za-z0-9]{1,8}"))ext="mp4";return server+"/"+(kind.equals("live")?"live":kind.equals("vod")?"movie":"series")+"/"+enc(user)+"/"+enc(password)+"/"+id+"."+(kind.equals("live")?format:ext);}
}
